/// Deal 7/10 damage and draw four/five; discard exactly the drawn cards whose fully modified energy cost is nonzero, including X-cost cards.
/// Source: v0.111.0 Models.Cards/Scrape.cs.
pub(crate) fn play_scrape(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Scrape: Enemy-targeted");
    let base = current_card_damage(state);
    let _ = deal_damage_player_to_enemy(state, t, base);
    let draws = if current_card_upgraded(state) { 5 } else { 4 };
    state.draw_with_followup(
        draws,
        sts2_core::DrawFollowup::ScrapeDiscardNonzero,
        discard_drawn_nonzero,
    );
    EffectResult::Resolved
}

fn discard_drawn_nonzero(
    state: &mut CombatState,
    _source: Option<sts2_core::CardUid>,
    cards: &[sts2_core::CardUid],
) {
    let to_discard: smallvec::SmallVec<[sts2_core::CardUid; 8]> = cards
        .iter()
        .copied()
        .filter(|uid| {
            let card = &state.cards[uid.0.get() as usize - 1];
            card.cost < 0 || sts2_core::hooks::effective_card_cost(state, *uid) != 0
        })
        .collect();
    let _ = sts2_core::card_effects::discard_and_draw_with_hooks(state, &to_discard, 0);
}

